// Grant triggers serialize with native audit transactions. A synchronous psql
// wait would prevent this process from delivering those transactions' COMMIT.
async function editOwnedProtectedGrant(statement:string){
 const receipt=readReceipt(process.env['VNEXT_TEST_RECEIPT']);
 if(receipt.taskId!=='P3-10'||receipt.purpose!=='TEMPORARY_VALIDATION'||receipt.name!==context.receipt.name||receipt.oid!==context.receipt.oid)throw new Error('OWNED_TEST_DATABASE_REQUIRED');
 await peerAsync(receipt,statement);
}
beforeAll(async()=>{
 const connection=process.env['VNEXT_VALIDATION_OWNER_URL']!,receipt=JSON.parse(readFileSync(process.env['VNEXT_TEST_RECEIPT']!,'utf8')),provider=validationKeys(receipt);
 const {Pool}=await import('pg');const pool=new Pool({connectionString:connection});const role=(await pool.query('select current_user r')).rows[0].r;await pool.end();
 catalog=await openCatalog(connection,provider);fixture=await businessUnitFixture(receipt,role,catalog,provider,connection,process.env['VNEXT_P3_10_POPULATED']==='1');
 context={connection,receipt,role,provider};ports.UNIT=fixture.owner;validation=openCareValidation(connection,ports);provisionCareWorkspace(receipt,role);workspace=openCareWorkspace(connection,provider,ports);
 const requestActor=(r:FastifyRequest)=>actor(r.headers);
 server=await buildCatalogServer(catalog,'CONTROL_PLANE',
  undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,
  {get owner(){if(!capabilities)throw new Error('BLOCKED_DEPENDENCY');return capabilities.values;},actor:requestActor},undefined,
  {get owner(){if(!subjects)throw new Error('BLOCKED_DEPENDENCY');return subjects.codes;},actor:requestActor},
  {get owner(){if(!subjects)throw new Error('BLOCKED_DEPENDENCY');return subjects.owner;},actor:requestActor},undefined,
  {get owner(){if(!coverages)throw new Error('BLOCKED_DEPENDENCY');return coverages.owner;},actor:requestActor},undefined,undefined,
  {owner:validation,actor:requestActor},{owner:workspace,actor:requestActor});url=await server.listen({host:'127.0.0.1',port:0});
});
afterAll(async()=>{await server?.close();await validation?.close();await workspace?.close();await lifecycle?.close();await subjects?.close();await unitWards?.close();await coverages?.close();await capabilities?.close();await space?.close();await fixture?.close();await catalog?.close();});

async function suspendDepartmentWindow(base:typeof fixture,department:string,T:string,U:string){
 for(const[action,head,at]of [['SUSPEND','0',T],['RESUME','1',U]] as const){const job=await base.dep.newJob(),staged=await base.lifecycle.stage('maker',{requestId:randomUUID(),jobId:job.id,revisionId:job.revisionId,campus:'NORTH',profile:'CORE',commands:[{action,department:{owner:'department-master',id:department,expectedVersion:'1',expectedLifecycleHead:head},effectiveAt:at,reason:'TEST native staged temporal counterexample',evidenceId:base.dep.artifact.artifactId}],impacts:base.impacts.map(impact=>({...impact,determination:['IDENTIFIER','SOURCE_MAPPING','HIERARCHY'].includes(impact.domain)?'AFFECTED' as const:impact.determination}))});await base.lifecycle.verify('reviewer',{requestId:randomUUID(),inputId:staged.inputId,inputDigest:staged.digest,reason:'TEST independent parent interval',policyApproved:true,materialsAccepted:true,impactReviews:base.impactReviews});const requestId=randomUUID(),candidate=await base.lifecycle.plan('maker',{inputId:staged.inputId,requestId});await base.lifecycle.readApplyCandidate('reviewer',{candidateId:candidate.candidateId});await base.lifecycle.approveApplyUnit('reviewer',candidate);expect((await base.lifecycle.applyUnit('maker',{candidateId:candidate.candidateId,requestId})).status).toBe('COMMITTED');}
}
