test('AC02 suspension in the middle reports the exact microsecond counterexample and old R stays valid',async()=>{
 const binding=await fixture.endpoint(await fixture.newDepartment()),entry=fixture.entry(binding),outcome=await fixture.apply(await fixture.input([entry])),id=outcome.facts[0]!.id;
 if(entry.action!=='CREATE')throw new Error('FIXTURE_INVALID');const {binding:_,...native}=entry;
 for(const [action,head,at] of [['SUSPEND','1','2027-02-01T00:00:00.000001'],['RESUME','2','2027-03-01T00:00:00.000001']] as const)await fixture.apply(await fixture.input([{...native,action,target:{owner:'care-organization/unit',id,expectedHead:head},row:{...entry.row,valid_from:at,record_status:action==='SUSPEND'?'SUSPENDED':'ACTIVE'}}]));
 const input={mode:'CURRENT_ADMISSION',profile:'CORE',validFrom:'2027-01-01T00:00:00',validTo:'2027-04-01T00:00:00',targets:[{owner:'UNIT',id,campusId:binding.campus.id}],members:[]};
 const call=async(body:unknown)=>{const response=await fetch(url+'/api/vnext/care-organization/validate-bundle',{method:'POST',headers:{'content-type':'application/json','x-catalog-actor':'maker'},body:JSON.stringify(body)});expect(response.status).toBe(200);return response.json();};
 const now=await call(input);expect(now.decision).toBe('FAIL');expect(now.items).toEqual(expect.arrayContaining([expect.objectContaining({from:'2027-02-01T00:00:00.000001',to:'2027-03-01T00:00:00.000001',status:'NOT_SATISFIED'})]));
 const old=await call({...input,mode:'HISTORICAL',recordAsOf:outcome.recordedAt});expect(old.decision).toBe('PASS');expect(old.recordAsOf).toBe(outcome.recordedAt);
});
