test('AC05 an independent event-interval oracle agrees with real HTTP across partial revisions, lifecycle and old R',async()=>{
 // Oracle uses explicit integer event intervals; it imports no production time,
 // interval, version-selection or coverage helper.
 const micro=(stamp:string)=>{const [whole,fraction='']=stamp.split('.');return BigInt(Date.parse(whole!+'Z'))*1000n+BigInt(fraction.padEnd(6,'0'));};
 const from='2027-01-01T00:00:00',to='2028-01-01T00:00:00',binding=await fixture.endpoint(await fixture.newDepartment()),entry=fixture.entry(binding),created=await fixture.apply(await fixture.input([entry]));if(entry.action!=='CREATE')throw new Error('FIXTURE_INVALID');const id=created.facts[0]!.id,{binding:_,...native}=entry;
 const events=[{at:'2027-02-01T00:00:00.000001',action:'SUSPEND' as const},{at:'2027-03-01T00:00:00.000001',action:'RESUME' as const},{at:'2027-10-01T00:00:00.000001',action:'CLOSE' as const}];
 const partial=await fixture.input([{...native,action:'REVISE',target:{owner:'care-organization/unit',id,expectedHead:'1'},row:{...entry.row,unit_name:'TEST 局部期间修订',valid_from:'2027-05-01T00:00:00.000001',valid_to:'2027-06-01T00:00:00.000001'}}]);await fixture.apply(partial);
 for(const [index,event] of events.entries())await fixture.apply(await fixture.input([{...native,action:event.action,target:{owner:'care-organization/unit',id,expectedHead:String(index+2)},row:{...entry.row,valid_from:event.at,record_status:event.action==='RESUME'?'ACTIVE':event.action==='CLOSE'?'RETIRED':'SUSPENDED'}}]));
 const client=createCareValidationClient(url,'maker'),query={mode:'CURRENT_ADMISSION' as const,profile:'CORE' as const,validFrom:from,validTo:to,targets:[{owner:'UNIT' as const,id,campusId:binding.campus.id}],members:[]},result=await client.validateCareOrganizationBundle(query);expect(result.response.status,JSON.stringify(result.error)).toBe(200);expect(result.data?.decision).toBe('FAIL');
 const boundaries=[from,...events.map(event=>event.at),'2027-05-01T00:00:00.000001','2027-06-01T00:00:00.000001',to].sort((a,b)=>micro(a)<micro(b)?-1:1),oracle=boundaries.slice(0,-1).map((at,index)=>{const event=events.filter(event=>micro(event.at)<=micro(at)).at(-1);return {from:micro(at),to:micro(boundaries[index+1]!),status:!event||event.action==='RESUME'?'SATISFIED':'NOT_SATISFIED'};});
 for(const expected of oracle){const overlaps=result.data!.items.filter(item=>micro(item.from)<=expected.from&&(item.to===null||micro(item.to)>=expected.to));expect(overlaps.some(item=>item.status===expected.status),JSON.stringify({expected:{...expected,from:String(expected.from),to:String(expected.to)},actual:result.data!.items})).toBe(true);}
 const old=await client.validateCareOrganizationBundle({...query,mode:'HISTORICAL',recordAsOf:created.recordedAt});expect(old.response.status).toBe(200);expect(old.data?.decision).toBe('PASS');expect(old.data?.items.every(item=>item.status==='SATISFIED')).toBe(true);
 const original=(await fixture.owner.history('maker',{id})).versions[0]!.facts.source.recordLocatorEvidence;const beforeRevision=await client.validateCareOrganizationBundle({...query,validFrom:'2026-02-01T00:00:00',validTo:'2026-03-01T00:00:00'});expect(beforeRevision.data?.decision).toBe('PASS');expect(beforeRevision.data?.items.every(item=>item.inputId===original.inputId)).toBe(true);
});
